// Shadertoy code - Ocean Plane & Centered Jello Cube

#define PI 3.14159265359
#define MAX_STEPS 100
#define MAX_DIST 20.0
#define SURF_DIST 0.001

// Add 2D noise functions
float hash(float n) { return fract(sin(n) * 43758.5453); }
float hash(vec2 p) { return fract(1e4 * sin(17.0 * p.x + p.y * 0.1) * (0.1 + abs(sin(p.y * 13.0 + p.x)))); }



float sdCube(vec3 p, vec3 s) {
    p = abs(p) - s;
    return length(max(p,0.0)) + min(max(p.x,max(p.y,p.z)),0.0);
}

float noise(vec3 x) {
    vec3 p = floor(x);
    vec3 f = fract(x);
    f = f*f*(3.0-2.0*f);
    float n = p.x + p.y*157.0 + 113.0*p.z;
    return mix(mix(mix(hash(n+0.0), hash(n+1.0),f.x),
                   mix(hash(n+157.0), hash(n+158.0),f.x),f.y),
               mix(mix(hash(n+113.0), hash(n+114.0),f.x),
                   mix(hash(n+270.0), hash(n+271.0),f.x),f.y),f.z);
}
mat2 rot(float a) {
    float s = sin(a), c = cos(a);
    return mat2(c, -s, s, c);
}
float noise(vec2 x) {
    vec2 i = floor(x);
    vec2 f = fract(x);
    float a = hash(i);
    float b = hash(i + vec2(1.0, 0.0));
    float c = hash(i + vec2(0.0, 1.0));
    float d = hash(i + vec2(1.0, 1.0));
    vec2 u = f * f * (3.0 - 2.0 * f);
    return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}
float mapJello(vec3 p) {
    float t = iTime;

    // Center cube at (0,0,0) before transformations
    p.y += 0.5; // Vertical centering adjustment

    // Scale cube uniformly (0.5 = half-unit cube)
    float cubeScale = 1.5;
    p /= cubeScale; // Inverse scale for SDF

    // Animate cube
    p.xy *= rot(t*0.5);
    p.xz *= rot(t*0.3);

    // Jiggle deformation
    vec3 q = p;
    q.x += sin(t*2.0 + p.y*3.0)*0.2;
    q.z += cos(t*1.5 + p.y*2.0)*0.2;
    q.y += sin(t*1.7 + p.x*2.0)*0.1;

    // Apply scaling to SDF
    return sdCube(q, vec3(1.0)) * cubeScale - 0.05*sin(t*5.0 + p.x*10.0)*sin(t*3.0 + p.z*10.0);
}

float mapOcean(vec3 p) {
    float wave = sin(p.x*2.0 + iTime*2.0) * 
               sin(p.z*1.5 + iTime*1.7) * 0.3 +
               noise(p.xz*0.5 + iTime*0.5) * 0.2; // Now using 2D noise
    return p.y + 1.0 + wave*0.5;
}
vec3 getNormal(vec3 p) {
    vec2 e = vec2(0.01, 0);
    float d = mapOcean(p);
    return normalize(vec3(
        mapOcean(p + e.xyy) - d,
        mapOcean(p + e.yxy) - d,
        mapOcean(p + e.yyx) - d
    ));
}

float rayMarch(vec3 ro, vec3 rd) {
    float dO = 0.0;
    for(int i = 0; i < MAX_STEPS; i++) {
        vec3 p = ro + rd * dO;
        float dS = min(mapJello(p), mapOcean(p));
        dO += dS;
        if(dO > MAX_DIST || abs(dS) < SURF_DIST) break;
    }
    return dO;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord - 0.5*iResolution.xy)/iResolution.y;
    vec3 col = vec3(0.5,0.7,1.0);

    // Camera setup
    vec3 ro = vec3(0, 1.5, 4); // Move camera back and slightly higher
    ro.yz *= rot(-PI*0.15); // Reduce camera tilt angle
    vec3 rd = normalize(vec3(uv, -1));
    rd.yz *= rot(-PI*0.2);

    // Raymarch scene
    float d = rayMarch(ro, rd);
    vec3 p = ro + rd * d;

    // Ocean shading
    if(mapOcean(p) < mapJello(p)) {
        vec3 n = getNormal(p);
        vec3 water = vec3(0.2, 0.4, 0.8);
        float fresnel = pow(1.0 - dot(n, -rd), 4.0);
        vec3 refl = texture(iChannel0, reflect(rd, n).xy).rgb;
        col = mix(water*0.7, refl, fresnel);

        // Foam
        float foam = smoothstep(0.4, 0.6, 
            noise(p.xz*5.0 + iTime*2.0) + 
            sin(p.x*10.0 + iTime*5.0)*0.3 +
            sin(p.z*8.0 + iTime*3.0)*0.3
        );
        col = mix(col, vec3(1), foam*0.3);
    }
    // Jello cube shading
    else {
        vec3 n = getNormal(p);
        vec3 lightPos = vec3(2, 5, 3);
        vec3 lightDir = normalize(lightPos - p);
        float dif = clamp(dot(n, lightDir), 0.0, 1.0);
        float spec = pow(clamp(dot(reflect(-lightDir, n), -rd), 0.0, 1.0), 32.0);

        vec3 jelloColor = vec3(1.0, 0.6, 0.5);
        col = jelloColor * (dif + 0.3) + spec*0.5;
        col *= 0.8 + 0.2*sin(p*10.0 + iTime*5.0);
    }

    // Fog
    col = mix(col, vec3(0.5,0.7,1.0), 1.0 - exp(-0.1*d*d));

    fragColor = vec4(col, 1.0);
}
